+@page "/track"
+@page "/track/{TrackingNumber}"
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+
+<PageTitle>Track Shipment</PageTitle>
+
+<div class="container py-4">
+    <h1 class="mb-4">🔍 Track Your Shipment</h1>
+
+    <div class="row mb-4">
+        <div class="col-md-6">
+            <div class="input-group">
+                <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-100001)" @bind="inputTrackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
+                <button class="btn btn-primary" @onclick="Search" disabled="@isLoading">
+                    @if (isLoading)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                    }
+                    Track
+                </button>
+            </div>
+        </div>
+    </div>
+
+    @if (searched && shipment is null && !isLoading)
+    {
+        <div class="alert alert-warning">
+            <strong>Not found.</strong> No shipment found with tracking number <code>@searchedNumber</code>. Please double-check and try again.
+        </div>
+    }
+
+    @if (shipment is not null)
+    {
+        <div class="card shadow-sm">
+            <div class="card-header d-flex justify-content-between align-items-center">
+                <h5 class="mb-0">Tracking: <code>@shipment.TrackingNumber</code></h5>
+                <span class="badge @StatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span>
+            </div>
+            <div class="card-body">
+                <div class="row g-3">
+                    <div class="col-md-6">
+                        <dl class="row mb-0">
+                            <dt class="col-sm-5">Recipient</dt>
+                            <dd class="col-sm-7">@shipment.RecipientName</dd>
+
+                            <dt class="col-sm-5">Origin</dt>
+                            <dd class="col-sm-7">@shipment.Origin</dd>
+
+                            <dt class="col-sm-5">Destination</dt>
+                            <dd class="col-sm-7">@shipment.Destination</dd>
+
+                            <dt class="col-sm-5">Carrier</dt>
+                            <dd class="col-sm-7">@shipment.CarrierName</dd>
+                        </dl>
+                    </div>
+                    <div class="col-md-6">
+                        <dl class="row mb-0">
+                            <dt class="col-sm-5">Weight</dt>
+                            <dd class="col-sm-7">@($"{shipment.WeightKg:F1} kg")</dd>
+
+                            <dt class="col-sm-5">Shipped</dt>
+                            <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
+
+                            <dt class="col-sm-5">Est. Delivery</dt>
+                            <dd class="col-sm-7 fw-bold">@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
+
+                            @if (shipment.ActualDelivery.HasValue)
+                            {
+                                <dt class="col-sm-5">Delivered On</dt>
+                                <dd class="col-sm-7 text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
+                            }
+                        </dl>
+                    </div>
+                </div>
+
+                @{
+                    var steps = GetProgressSteps(shipment.Status);
+                }
+                <hr />
+                <h6>Shipment Progress</h6>
+                <div class="d-flex justify-content-between mt-3">
+                    @foreach (var (label, reached) in steps)
+                    {
+                        <div class="text-center flex-fill">
+                            <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(reached ? "bg-primary" : "bg-secondary bg-opacity-25") text-white" style="width:36px;height:36px;">
+                                @if (reached)
+                                {
+                                    <span>✓</span>
+                                }
+                            </div>
+                            <div class="small mt-1 @(reached ? "fw-semibold" : "text-body-secondary")">@label</div>
+                        </div>
+                    }
+                </div>
+            </div>
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter] public string? TrackingNumber { get; set; }
+    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
+    [Inject] private NavigationManager Navigation { get; set; } = default!;
+
+    private string inputTrackingNumber = string.Empty;
+    private Shipment? shipment;
+    private bool isLoading;
+    private bool searched;
+    private string? searchedNumber;
+
+    protected override async Task OnParametersSetAsync()
+    {
+        if (!string.IsNullOrWhiteSpace(TrackingNumber))
+        {
+            inputTrackingNumber = TrackingNumber;
+            await Search();
+        }
+    }
+
+    private void HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+        {
+            _ = Search();
+        }
+    }
+
+    private async Task Search()
+    {
+        if (string.IsNullOrWhiteSpace(inputTrackingNumber)) return;
+
+        isLoading = true;
+        searched = true;
+        searchedNumber = inputTrackingNumber.Trim();
+        shipment = null;
+
+        try
+        {
+            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
+        }
+        catch
+        {
+            shipment = null;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static List<(string Label, bool Reached)> GetProgressSteps(ShipmentStatus status)
+    {
+        var order = new[] { ShipmentStatus.Pending, ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Delivered };
+        var labels = new[] { "Pending", "Picked Up", "In Transit", "Out for Delivery", "Delivered" };
+
+        if (status == ShipmentStatus.Delayed)
+        {
+            return labels.Select((l, i) => (l, false)).Append(("⚠ Delayed", true)).ToList();
+        }
+        if (status == ShipmentStatus.Returned)
+        {
+            return labels.Select((l, i) => (l, false)).Append(("↩ Returned", true)).ToList();
+        }
+
+        var currentIndex = Array.IndexOf(order, status);
+        return labels.Select((l, i) => (l, i <= currentIndex)).ToList();
+    }
+
+    private static string FormatStatus(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "Pending",
+        ShipmentStatus.PickedUp => "Picked Up",
+        ShipmentStatus.InTransit => "In Transit",
+        ShipmentStatus.OutForDelivery => "Out for Delivery",
+        ShipmentStatus.Delivered => "Delivered",
+        ShipmentStatus.Delayed => "Delayed",
+        ShipmentStatus.Returned => "Returned",
+        _ => status.ToString()
+    };
+
+    private static string StatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info text-dark",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Delayed => "bg-danger",
+        ShipmentStatus.Returned => "bg-dark",
+        _ => "bg-secondary"
+    };
+}
+

