@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<Shipment>? shipments;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrEmpty(statusFilter) && s.Status.ToString() != statusFilter)
                return false;
            if (!string.IsNullOrEmpty(searchTerm))
            {
                var term = searchTerm.Trim();
                return s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase)
                    || s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase)
                    || s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase);
            }
            return true;
        });

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ShipmentStatus newStatus)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private static IEnumerable<ShipmentStatus> GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Delayed],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Delayed, ShipmentStatus.Returned],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Delayed, ShipmentStatus.Returned],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Delayed, ShipmentStatus.Returned],
        ShipmentStatus.Delayed => [ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Returned],
        _ => []
    };

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Delayed => "Delayed",
        ShipmentStatus.Returned => "Returned",
        _ => status.ToString()
    };

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}
